describe("AuthStorage OAuth login upgrade and multi-account coexistence", () => {
	let tempDir = "";

	beforeEach(async () => {
		tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "omp-auth-login-test-"));
	});

	afterEach(async () => {
		unregisterOAuthProviders("auth-storage-login-upgrade-test");
		if (tempDir) {
			await removeWithRetries(tempDir);
		}
	});

	it("allows multiple OAuth accounts to coexist and replaces legacy api_key rows on OAuth login", async () => {
		if (!tempDir) throw new Error("test setup failed");

		const dbPath = path.join(tempDir, "login-upgrade.db");
		const authStorage = await AuthStorage.create(dbPath);

		try {
			// 1. Setup a legacy api_key credential
			await authStorage.credentials.set("unit-login-upgrade", { type: "api_key", key: "sk-legacy-key" });
			expect(await authStorage.keys.get("unit-login-upgrade")).toBe("sk-legacy-key");

			// 2. Register custom oauth provider
			let loginReturns: (Omit<OAuthCredential, "type"> & { type?: string }) | null = null;
			registerOAuthProvider({
				id: "unit-login-upgrade",
				name: "Unit Login Upgrade",
				sourceId: "auth-storage-login-upgrade-test",
				login: async () => {
					if (!loginReturns) throw new Error("no credentials");
					const { type: _type, ...rest } = loginReturns;
					return rest;
				},
				refreshToken: async () => {
					if (!loginReturns) throw new Error("no credentials");
					const { type: _type, ...rest } = loginReturns;
					return rest;
				},
			});

			// 3. Login first OAuth account
			loginReturns = {
				refresh: "refresh-token-1",
				access: "access-token-1",
				expires: Date.now() + 60_000,
				projectId: "project-1",
				email: "user-1@example.com",
			};
			await authStorage.oauth.login("unit-login-upgrade", {
				onAuth: () => {},
				onPrompt: async () => "",
			});

			// Legacy api_key should be gone/replaced, and first oauth account is active.
			// getApiKey should now return the first OAuth access token (since the api_key is gone).
			expect(await authStorage.keys.get("unit-login-upgrade")).toBe("access-token-1");
			const firstRows = readStoredIdentityRows(dbPath, "unit-login-upgrade");
			expect(firstRows).toEqual([
				{ identity_key: null, disabled_cause: "replaced by oauth login" },
				{ identity_key: "email:user-1@example.com", disabled_cause: null },
			]);

			// 4. Login second OAuth account
			loginReturns = {
				refresh: "refresh-token-2",
				access: "access-token-2",
				expires: Date.now() + 60_000,
				projectId: "project-2",
				email: "user-2@example.com",
			};
			await authStorage.oauth.login("unit-login-upgrade", {
				onAuth: () => {},
				onPrompt: async () => "",
			});

			// Both OAuth accounts should coexist! No accounts should be disabled
			const secondRows = readStoredIdentityRows(dbPath, "unit-login-upgrade");
			expect(secondRows).toEqual([
				{ identity_key: null, disabled_cause: "replaced by oauth login" },
				{ identity_key: "email:user-1@example.com", disabled_cause: null },
				{ identity_key: "email:user-2@example.com", disabled_cause: null },
			]);
		} finally {
			authStorage.close();
		}
	});

	it("keeps existing NVIDIA API keys active when login adds another key", async () => {
		if (!tempDir) throw new Error("test setup failed");

		const dbPath = path.join(tempDir, "api-key-rotation.db");
		const authStorage = await AuthStorage.create(dbPath);
		const prompts = ["nvapi-first", "nvapi-second"];
		const fetchMock: FetchImpl = async () =>
			new Response("{}", { status: 200, headers: { "Content-Type": "application/json" } });

		try {
			await authStorage.oauth.login("nvidia", {
				onAuth: () => {},
				onPrompt: async () => prompts.shift() ?? "",
				fetch: fetchMock,
			});
			await authStorage.oauth.login("nvidia", {
				onAuth: () => {},
				onPrompt: async () => prompts.shift() ?? "",
				fetch: fetchMock,
			});

			expect(authStorage.credentials.list("nvidia").map(entry => entry.credential)).toEqual([
				{ type: "api_key", key: "nvapi-first", source: "login" },
				{ type: "api_key", key: "nvapi-second", source: "login" },
			]);

			const selectedKeys = new Set<string>();
			for (let index = 0; index < 64; index += 1) {
				const key = await authStorage.keys.get("nvidia", `session-${index}`);
				if (key) selectedKeys.add(key);
			}
			expect(selectedKeys).toEqual(new Set(["nvapi-first", "nvapi-second"]));
		} finally {
			authStorage.close();
		}
	});
});

describe("AuthStorage persistent session stickiness", () => {
	let tempDir = "";
	let dbPath = "";

	beforeEach(async () => {
		tempDir = await fs.mkdtemp(path.join(os.tmpdir(), "omp-auth-test-"));
		dbPath = path.join(tempDir, "auth.db");
	});

	afterEach(async () => {
		await removeWithRetries(tempDir);
	});

	it("persists session-sticky credentials across AuthStorage restarts", async () => {
		// 1. Initialize AuthStorage and log in two accounts
		let authStorage = new AuthStorage(new SqliteAuthCredentialStore(new Database(dbPath)));

		try {
			const credential1: OAuthCredential = {
				type: "oauth",
				refresh: "refresh-token-1",
				access: "access-token-1",
				expires: Date.now() + 3600_000,
				projectId: "project-1",
				email: "user-1@example.com",
			};
			const credential2: OAuthCredential = {
				type: "oauth",
				refresh: "refresh-token-2",
				access: "access-token-2",
				expires: Date.now() + 3600_000,
				projectId: "project-2",
				email: "user-2@example.com",
			};
			await authStorage.credentials.set("unit-session-stickiness", [credential1, credential2]);

			// 2. Resolve initial key for session-1
			const key1 = await authStorage.keys.get("unit-session-stickiness", "session-1");
			expect(key1).toBe("access-token-2");

			// 3. Rotate session-1's sticky credential to the sibling
			await authStorage.limits.rotate("unit-session-stickiness", "session-1");
			const key2 = await authStorage.keys.get("unit-session-stickiness", "session-1");
			expect(key2).toBe("access-token-1");

			// 4. Close AuthStorage to simulate process restart
			authStorage.close();

			// 5. Re-instantiate AuthStorage using the same DB
			authStorage = new AuthStorage(new SqliteAuthCredentialStore(new Database(dbPath)));
			await authStorage.credentials.reload();

			// 6. Retrieve the sticky key again for session-1 (should still be access-token-1)
			const key3 = await authStorage.keys.get("unit-session-stickiness", "session-1");
			expect(key3).toBe("access-token-1");

			authStorage.close();
		} finally {
			// No-op
		}
	});

	it("drops persisted session stickiness after a lower-index credential is removed", async () => {
		const provider = "unit-sticky-invalidation";
		const mk = (suffix: string): OAuthCredential => ({
			type: "oauth",
			refresh: `refresh-${suffix}`,
			access: `access-${suffix}`,
			expires: Date.now() + 3600_000,
			projectId: `project-${suffix}`,
			email: `user-${suffix}@example.com`,
		});
		const initialCredentials = [mk("a"), mk("b"), mk("c"), mk("d")];
		const remainingCredentials = initialCredentials.slice(1);

		let authStorage = new AuthStorage(new SqliteAuthCredentialStore(new Database(dbPath)));
		await authStorage.credentials.set(provider, initialCredentials);
		let rows = authStorage.credentials.list(provider);

		const control = new AuthStorage(
			new SqliteAuthCredentialStore(new Database(path.join(tempDir, "sticky-control.db"))),
		);
		await control.credentials.set(provider, remainingCredentials);
		let session: string | undefined;
		let stuckId = -1;
		let stuckIndex = -1;
		let stuckToken: string | undefined;
		let freshToken: string | undefined;
		try {
			for (let i = 0; i < 256 && session === undefined; i++) {
				const candidate = `sticky-probe-${i}`;
				const token = await authStorage.keys.get(provider, candidate);
				const expectedFreshToken = await control.keys.get(provider, candidate);
				const index = rows.findIndex(row => (row.credential as OAuthCredential).access === token);
				if (index >= 1 && index <= rows.length - 2 && token !== expectedFreshToken) {
					session = candidate;
					stuckIndex = index;
					stuckId = rows[index].id;
					stuckToken = token;
					freshToken = expectedFreshToken;
				}
			}
		} finally {
			control.close();
		}
		expect(session).toBeDefined();
		expect(freshToken).toBeDefined();

		expect(await authStorage.credentials.removeById(provider, rows[0].id)).toBe(true);
		authStorage.close();

		authStorage = new AuthStorage(new SqliteAuthCredentialStore(new Database(dbPath)));
		await authStorage.credentials.reload();
		rows = authStorage.credentials.list(provider);
		expect(rows.findIndex(row => row.id === stuckId)).toBe(stuckIndex - 1);

		const resolved = await authStorage.keys.get(provider, session);
		authStorage.close();
		expect(resolved).toBe(freshToken);
		expect(resolved).not.toBe(stuckToken);
	});
});

/**
 * Tests for the new usage-cache contracts introduced after the broker
 * migration surfaced Anthropic per-IP rate limits:
 *
 *   1. Per-credential cache stores the last successful report; failures
 *      DON'T overwrite a stale-but-good entry with null.
 *   2. With a stale-but-good entry, a failure serves the previous value
 *      (cached for a short cool-down) instead of dropping the credential
 *      from the report.
 *   3. Without a previous value (a cold failure), a failure caches `null` for
 *      the failure backoff window — a repeat poll within the window is served
 *      from cache (no refetch); the entry expires and the next poll retries.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "bun:test";
import {
	type AuthCredential,
	type AuthCredentialStore,
	AuthStorage,
	type StoredAuthCredential,
} from "@oh-my-pi/pi-ai/auth-storage";
import type { UsageLimit, UsageProvider, UsageReport } from "@oh-my-pi/pi-ai/usage";
import { alibabaTokenPlanUsageProvider } from "@oh-my-pi/pi-ai/usage/alibaba-token-plan";
import * as claudeUsage from "@oh-my-pi/pi-ai/usage/claude";
import { serializeAlibabaTokenPlanCredential } from "@oh-my-pi/pi-catalog/wire/alibaba-token-plan";

function anthropicReports(reports: UsageReport[] | null): UsageReport[] {
	return (reports ?? []).filter(r => r.provider === "anthropic");
}

function requireAnthropicReport(reports: UsageReport[] | null): UsageReport {
	const report = anthropicReports(reports)[0];
	if (!report) throw new Error("expected anthropic usage report");
	return report;
}

function requireLimit(report: UsageReport, id: string): UsageLimit {
	const limit = report.limits.find(candidate => candidate.id === id);
	if (!limit) throw new Error(`expected ${id} limit`);
	return limit;
}

/**
 * Force every cache entry to look stale to AuthStorage WITHOUT dropping the
 * value. The cache layer is two-tier: the store-level `expiresAtSec` controls
 * whether `getCache` returns anything at all, and the JSON payload's own
 * `expiresAt` is what AuthStorage compares against `Date.now()` to decide if
 * the entry is fresh. Mutating only the inner expiresAt simulates time
 * passing while keeping the last-good value reachable for the failure path.
 */
function expireCachePayloads(store: ObservableStore): void {
	for (const [key, entry] of store.cache) {
		try {
			const parsed = JSON.parse(entry.value);
			parsed.expiresAt = 1; // positive but already in the past (epoch ms)
			store.cache.set(key, { value: JSON.stringify(parsed), expiresAtSec: entry.expiresAtSec });
		} catch {
			// Non-JSON entries — leave alone.
		}
	}
}

interface CacheEntry {
	value: string;
	expiresAtSec: number;
}

interface ObservableStore extends AuthCredentialStore {
	cache: Map<string, CacheEntry>;
}

/**
 * Minimal in-memory `AuthCredentialStore` exposing the cache so we can
 * assert what AuthStorage writes to it during usage fetches.
 */
function makeStore(rows: StoredAuthCredential[]): ObservableStore {
	const cache = new Map<string, CacheEntry>();
	return {
		cache,
		close() {},
		listAuthCredentials() {
			return rows;
		},
		updateAuthCredential() {},
		async deleteAuthCredential() {
			return false;
		},
		tryDisableAuthCredentialIfMatches() {
			return false;
		},
		async replaceAuthCredentials() {
			return rows;
		},
		async upsertAuthCredential() {
			return rows;
		},
		async deleteAuthCredentials() {},
		getCache(key) {
			const entry = cache.get(key);
			if (!entry) return null;
			if (entry.expiresAtSec * 1000 <= Date.now()) return null;
			return entry.value;
		},
		setCache(key, value, expiresAtSec) {
			cache.set(key, { value, expiresAtSec });
		},
		cleanExpiredCache() {},
	};
}

function oauthRow(id: number, email: string): StoredAuthCredential {
