import { describe, expect, it } from "bun:test";
import type { CompactionSettings } from "@oh-my-pi/pi-agent-core/compaction/compaction";
import {
	DEFAULT_COMPACTION_SETTINGS,
	effectiveReserveTokens,
	resolveBudgetReserveTokens,
	resolveThresholdTokens,
	shouldCompact,
} from "@oh-my-pi/pi-agent-core/compaction/compaction";

describe("compaction reserve provenance", () => {
	it("honors an explicit reserve equal to the default on a small window", () => {
		// cw=19000: proportional would be floor(19000*0.15)=2850, but the reserve
		// was explicitly configured — even though it equals DEFAULT_RESERVE_TOKENS,
		// provenance says "user chose this", so it must win.
		const settings: CompactionSettings = {
			enabled: true,
			thresholdPercent: -1,
			reserveTokens: 16384,
			keepRecentTokens: 20000,
		};
		const cw = 19000;
		expect(effectiveReserveTokens(cw, settings)).toBe(16384);
		expect(resolveBudgetReserveTokens(cw, settings)).toBe(16384);
		expect(resolveThresholdTokens(cw, settings)).toBe(2616); // 19000 - 16384
		expect(shouldCompact(2616, cw, settings)).toBe(false);
		expect(shouldCompact(2617, cw, settings)).toBe(true);
	});

	it("replaces a defaulted reserve with the proportional fallback on the same window", () => {
		// Identical window, but reserveTokens is unset: 16384 >= 19000 - 2850, so
		// the defaulted reserve is effectively impossible and the 15% proportional
		// reserve (2850) takes over.
		const settings: CompactionSettings = {
			enabled: true,
			thresholdPercent: -1,
			keepRecentTokens: 20000,
		};
		const cw = 19000;
		expect(effectiveReserveTokens(cw, settings)).toBe(16384);
		expect(resolveBudgetReserveTokens(cw, settings)).toBe(2850); // floor(19000 * 0.15)
		expect(resolveThresholdTokens(cw, settings)).toBe(16150); // 19000 - 2850
		expect(shouldCompact(16150, cw, settings)).toBe(false);
		expect(shouldCompact(16151, cw, settings)).toBe(true);
	});

	it("keeps defaulted provenance when spreading DEFAULT_COMPACTION_SETTINGS", () => {
		// Spreading the defaults must not materialize reserveTokens; the spread
		// settings behave exactly like the omitted-field literal above.
		const settings: CompactionSettings = { ...DEFAULT_COMPACTION_SETTINGS, thresholdPercent: -1 };
		const cw = 19000;
		expect(settings.reserveTokens).toBeUndefined();
		expect(resolveBudgetReserveTokens(cw, settings)).toBe(2850);
		expect(resolveThresholdTokens(cw, settings)).toBe(16150);
		expect(shouldCompact(16150, cw, settings)).toBe(false);
		expect(shouldCompact(16151, cw, settings)).toBe(true);
	});

	it("clamps the proportional fallback to >= 1 and the threshold below the window on tiny windows", () => {
		const settings: CompactionSettings = {
			enabled: true,
			thresholdPercent: -1,
			keepRecentTokens: 20000,
		};
		for (let cw = 1; cw <= 10; cw++) {
			expect(resolveBudgetReserveTokens(cw, settings)).toBeGreaterThanOrEqual(1);
			expect(resolveThresholdTokens(cw, settings)).toBeLessThan(cw);
		}
		// Spot checks: floor(6 * 0.15) = 0 clamps to 1; threshold stays at cw - 1.
		expect(resolveBudgetReserveTokens(6, settings)).toBe(1);
		expect(resolveThresholdTokens(6, settings)).toBe(5);
		// Degenerate single-token window: reserve 1, threshold 0 (still < cw).
		expect(resolveBudgetReserveTokens(1, settings)).toBe(1);
		expect(resolveThresholdTokens(1, settings)).toBe(0);
	});

	it("recovers an explicit reserve that exceeds the window to the proportional reserve", () => {
		// reserveExceedsWindow applies regardless of provenance: an explicit 90000
		// on cw=16385 is impossible, so the budget falls back to floor(16385*0.15).
		const settings: CompactionSettings = {
			enabled: true,
			thresholdPercent: -1,
			reserveTokens: 90000,
			keepRecentTokens: 20000,
		};
		const cw = 16385;
		expect(effectiveReserveTokens(cw, settings)).toBe(90000);
		expect(resolveBudgetReserveTokens(cw, settings)).toBe(2457); // floor(16385 * 0.15)
	});
});

/**
 * Regression test for #1496 (bug 2): `omp install ./my-extension` used to be
 * silently rewritten to `launch install ./my-extension` and forwarded to the
 * LLM as an initial prompt because no top-level `install` subcommand existed.
 *
 * These tests pin two invariants:
 *
 *  1. `install` is registered in the CLI command table, so the runner does
 *     not prepend `launch` and the args never reach the model.
 *  2. The local-path heuristic that routes `install ./foo` to `plugin link`
 *     while routing remote specs to `plugin install` is correct for the
 *     shapes users actually type.
 */
import { describe, expect, test } from "bun:test";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { commands, isSubcommand, resolveCliArgv } from "@oh-my-pi/pi-coding-agent/cli-commands";
import { looksLikeLocalPath } from "@oh-my-pi/pi-coding-agent/commands/install";
import { removeSyncWithRetries } from "@oh-my-pi/pi-utils";

describe("install command is registered as a top-level subcommand", () => {
	test("CLI runner sees `install` as a known command", () => {
		expect(commands.some(c => c.name === "install")).toBe(true);
		expect(isSubcommand("install")).toBe(true);
	});

	test("CLI runner rejects only bare reserved management words", () => {
		expect(resolveCliArgv(["extensions"])).toEqual({
			error: '`omp extensions` is not a management command. Use `omp plugin list` / `omp plugin install`, or run `omp launch extensions` if you meant to send "extensions" as a prompt.',
		});
		expect(resolveCliArgv(["extensions", "are", "not", "loading"])).toEqual({
			argv: ["launch", "extensions", "are", "not", "loading"],
		});
		expect(resolveCliArgv(["launch", "extensions"])).toEqual({ argv: ["launch", "extensions"] });
	});
});

describe("looksLikeLocalPath", () => {
	test("explicit relative paths are local", () => {
		expect(looksLikeLocalPath("./my-extension")).toBe(true);
		expect(looksLikeLocalPath("../sibling")).toBe(true);
		expect(looksLikeLocalPath(".")).toBe(true);
	});

	test("absolute and home-relative paths are local", () => {
		expect(looksLikeLocalPath("/usr/local/share/ext")).toBe(true);
		expect(looksLikeLocalPath("~/extensions/foo")).toBe(true);
	});

	test("Windows drive-prefixed paths are local", () => {
		expect(looksLikeLocalPath("C:\\extensions\\foo")).toBe(true);
		expect(looksLikeLocalPath("D:/extensions/foo")).toBe(true);
	});

	test("npm specs and marketplace refs are remote", () => {
		expect(looksLikeLocalPath("@oh-my-pi/exa")).toBe(false);
		expect(looksLikeLocalPath("my-pkg")).toBe(false);
		expect(looksLikeLocalPath("my-pkg@1.2.3")).toBe(false);
		expect(looksLikeLocalPath("name@marketplace")).toBe(false);
	});

	test("bare names that exist as a local directory are treated as local", () => {
		const tempDir = fs.mkdtempSync(path.join(os.tmpdir(), "omp-install-test-"));
		try {
			fs.mkdirSync(path.join(tempDir, "vendored-ext"));
			expect(looksLikeLocalPath("vendored-ext", tempDir)).toBe(true);
			expect(looksLikeLocalPath("missing-pkg", tempDir)).toBe(false);
		} finally {
			removeSyncWithRetries(tempDir);
		}
	});
});

